const zone = 'Asia/Karachi';
const now = DateTime.now().setZone(zone);
const todayStr = now.toFormat('yyyy-LL-dd');
const tomorrow = now.plus({ days: 1 });
const tomorrowStr = tomorrow.toFormat('yyyy-LL-dd');

// Filter out empty-json items (alwaysOutputData produces {} on empty sheet)
const rows = $input.all()
  .map(i => i.json || {})
  .filter(r => Object.keys(r).length > 0);

function parseDate(v) {
  const raw = String(v || '').trim();
  if (!raw) return null;
  let dt = DateTime.fromISO(raw, { zone });
  if (!dt.isValid) dt = DateTime.fromISO(raw).setZone(zone);
  return dt.isValid ? dt : null;
}

const tomorrowAppts = [];
const todayCancellations = [];

for (const r of rows) {
  const status = String(r.status || '').toLowerCase().trim();
  const dt = parseDate(r.appointment_datetime);
  if (!dt) continue;
  const dayStr = dt.toFormat('yyyy-LL-dd');

  if ((status === 'booked' || status === 'confirmed') && dayStr === tomorrowStr) {
    tomorrowAppts.push({
      time: dt.toFormat('hh:mm a'),
      sortKey: dt.toMillis(),
      patient: String(r.patient_name || 'Unknown patient'),
      doctor: String(r.doctor || 'Unassigned'),
    });
  }
  if (status === 'cancelled' && dayStr === todayStr) {
    todayCancellations.push({
      time: dt.toFormat('hh:mm a'),
      patient: String(r.patient_name || 'Unknown patient'),
      doctor: String(r.doctor || 'Unassigned'),
    });
  }
}

tomorrowAppts.sort((a, b) => a.sortKey - b.sortKey);

// Build HTML lists
let apptRows = '';
if (tomorrowAppts.length) {
  for (const a of tomorrowAppts) {
    apptRows += '<li><strong>' + a.time + '</strong> — ' + a.patient + ' (with ' + a.doctor + ')</li>';
  }
} else {
  apptRows = '<li>No appointments scheduled for tomorrow.</li>';
}

let cancelRows = '';
if (todayCancellations.length) {
  for (const c of todayCancellations) {
    cancelRows += '<li>' + c.patient + ' — ' + c.time + ' (with ' + c.doctor + ')</li>';
  }
} else {
  cancelRows = '<li>No cancellations today.</li>';
}

const dateLabel = tomorrow.toFormat('cccc, dd LLL yyyy');

const html =
  '<div style="font-family:Arial,sans-serif;color:#222;line-height:1.5;">' +
  '<h2 style="color:#1a73e8;">Clinic Daily Summary</h2>' +
  '<p>Hello team,</p>' +
  '<p>Here is your end-of-day summary for ' + now.toFormat('cccc, dd LLL yyyy') + '.</p>' +
  '<h3>Tomorrow (' + dateLabel + '): ' + tomorrowAppts.length + ' appointment(s)</h3>' +
  '<ul>' + apptRows + '</ul>' +
  '<h3>Cancellations today: ' + todayCancellations.length + '</h3>' +
  '<ul>' + cancelRows + '</ul>' +
  '<p>Have a restful evening,<br/>The Clinic Automation</p>' +
  '</div>';

return [{
  json: {
    tomorrow_count: tomorrowAppts.length,
    cancellation_count: todayCancellations.length,
    date_label: dateLabel,
    summary_html: html,
  }
}];
